import{_ as o,o as a,c as s,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"Mais servidores","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/servers.md","filePath":"pt-BR/guide/servers.md"}'),i={name:"pt-BR/guide/servers.md"};function d(n,e,t,l,p,c){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="mais-servidores" tabindex="-1">Mais servidores <a class="header-anchor" href="#mais-servidores" aria-label="Permalink to &quot;Mais servidores&quot;">​</a></h1><h2 id="adding" tabindex="-1">Adicionando um <a class="header-anchor" href="#adding" aria-label="Permalink to &quot;Adicionando um {#adding}&quot;">​</a></h2><p><strong>Adicionar servidor</strong> no console: informe o nome, o IP e o usuário SSH do servidor, confirme a impressão digital da chave dele e autorize uma chave temporária (ou cole a sua). O Orbit roda as mesmas verificações e o mesmo plano da primeira máquina e, depois da sua aprovação, coloca o servidor no cluster como agente do K3s, com o seu próprio agente do Orbit. Serviços novos podem então ser colocados nele.</p><h3 id="discarding" tabindex="-1">Descartando um servidor <a class="header-anchor" href="#discarding" aria-label="Permalink to &quot;Descartando um servidor {#discarding}&quot;">​</a></h3><p>Um servidor que ainda não foi instalado pode ser descartado pelo setup dele ou com <strong>Descartar</strong> no card em Servidores, desde que nenhuma operação esteja rodando nele:</p><ul><li><p><strong>Antes de a instalação começar,</strong> nada foi instalado nele, e o Orbit o esquece junto com a chave temporária que gerou. Se você adicionou essa chave ao servidor, remova a linha dela de <code>~/.ssh/authorized_keys</code> lá.</p></li><li><p><strong>Depois de uma instalação que falhou,</strong> o Orbit primeiro tira o nó dele do cluster, revoga o agente dele e para de liberar os endereços dele no firewall do servidor principal. A máquina em si fica como está. Para usá-la em outra coisa, remova o que o Orbit instalou:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit-firewall</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/rancher/k3s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/orbit-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/orbit-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/lib/orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/orbit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /usr/local/bin/k3s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/orbit-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/system/k3s-agent.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /etc/systemd/system/orbit-agent.service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/system/orbit-firewall.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span></code></pre></div></li></ul><div class="info custom-block"><p class="custom-block-title">Mais servidores trazem espaço, não alta disponibilidade</p><p>Um serviço roda no servidor que você escolher e para se esse servidor parar, a menos que seja uma aplicação <a href="./applications#placement">espalhada entre servidores</a> ou um banco com <a href="./replicas">réplicas de PostgreSQL</a>. O tráfego entra pelo servidor principal, a menos que você escolha <a href="#entry">outros servidores para recebê-lo</a>.</p></div><h2 id="network" tabindex="-1">Requisitos de rede <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Requisitos de rede {#network}&quot;">​</a></h2><ul><li>Todo servidor precisa alcançar o IPv4 do servidor principal em TCP 6443 (Kubernetes) e 7443 (agentes do Orbit).</li><li>O servidor principal precisa alcançar todos os outros em TCP 10250 (logs e comandos).</li><li>Todos os servidores precisam se alcançar em UDP 51820 (WireGuard, que criptografa o tráfego entre eles).</li><li>O Orbit abre essas portas no servidor principal só para os seus servidores, pelo endereço público e pelo endereço numa rede privada que os servidores compartilhem. Quando o ufw está ativo num servidor, o Orbit também libera ali os endereços dos outros.</li><li><strong>Imagens que rejeitam tudo menos SSH,</strong> como as imagens Ubuntu da Oracle Cloud, cujas regras de iptables terminam em <code>REJECT</code>: o Orbit deixa os seus outros servidores passarem por elas no servidor principal e no novo, e as regras voltam depois de um reboot.</li><li><strong>Cada servidor mantém os endereços dos outros atualizados.</strong> Quando um servidor entra ou é descartado, e a cada dez minutos, o Orbit manda para cada servidor, pelo agente dele, os endereços de todos os outros (públicos, privados e os endereços deles no cluster), e o servidor reescreve a lista do firewall: servidores novos são liberados, pelo ufw também quando ele está ativo, e os que saíram são removidos.</li><li><strong>Redes privadas:</strong> quando o servidor principal tem um endereço privado (como nas redes da Oracle Cloud, AWS ou Hetzner), o servidor novo tenta esse endereço primeiro e depois o público. Antes de iniciar o K3s, ele confere se um dos dois responde na 6443, e se nenhum responder, a instalação para em segundos dizendo quais endereços tentou e de onde vem o tráfego. Quando os dois servidores estão na mesma rede privada, eles precisam se alcançar por ela: se só o endereço público responde, a instalação para ali e diz se o servidor principal recusou a conexão (o firewall dele) ou se nada respondeu (um firewall da nuvem), porque o tráfego entre os servidores seria recusado depois. Antes de iniciar o agente, o servidor novo também confere se alcança o canal dos agentes na 7443 e se o certificado dele cobre o endereço usado. Depois que ele entra, o Orbit confere a partir dele se as aplicações ali alcançam a API do Kubernetes e as aplicações de outro servidor, e para dizendo qual parte falhou se não alcançarem.</li><li><strong>Servidores em redes separadas,</strong> como duas VCNs da Oracle Cloud, dois provedores ou um servidor em casa e outro numa nuvem, entram pelos endereços públicos quando o servidor novo só alcança o principal por ali. O Orbit então faz o K3s anunciar o endereço público de cada servidor (<code>node-external-ip</code>), inclusive o da API do Kubernetes, e levar o tráfego entre os servidores por WireGuard entre esses endereços. O K3s do servidor principal reinicia uma vez para mudar, e as aplicações continuam rodando. O firewall de cada nuvem precisa deixar entrar o endereço público do outro servidor: TCP 6443 e 7443 e UDP 51820 no servidor principal, e UDP 51820 no novo (na Oracle, uma regra de entrada vinda de <code>&lt;endereço público&gt;/32</code> com todos os protocolos em cada VCN). Depois da mudança, servidores na própria rede do servidor principal também passam a alcançá-lo pelo endereço público. Um cluster com três servidores no plano de controle ainda não aceita servidores de outras redes.</li><li><strong>Firewalls da nuvem</strong> ficam fora do alcance do Orbit. Na Oracle Cloud, a security list da sub-rede só deixa passar SSH por padrão: adicione uma regra de entrada para a faixa da sub-rede (como <code>10.0.0.0/24</code>) com todos os protocolos. Quando o servidor principal roda na Oracle Cloud, um servidor que não consegue entrar diz isso: mostra a regra a adicionar, com a sub-rede do servidor novo como origem (ou o endereço público dele, quando está em outra rede), e um link para o servidor principal no console da Oracle, de onde a sub-rede e a security list ficam a um clique. Security groups da AWS e firewalls da Hetzner precisam das mesmas portas entre os seus servidores.</li></ul><p>A primeira entrada reinicia o K3s uma vez no servidor principal para ligar o WireGuard. As aplicações em execução continuam rodando.</p><h2 id="entry" tabindex="-1">Recebendo tráfego <a class="header-anchor" href="#entry" aria-label="Permalink to &quot;Recebendo tráfego {#entry}&quot;">​</a></h2><p>Por padrão, o tráfego entra pelo servidor principal. Outro servidor pronto também pode recebê-lo: <strong>Receber tráfego</strong> no cartão dele em Servidores. O Orbit passa a rodar o roteador nesse servidor também, espera ele ficar pronto e confere que o servidor responde na porta 80. Se não responder, o Orbit desfaz a mudança e avisa.</p><ul><li><strong>Firewall:</strong> abra TCP 80 e 443 para a internet no firewall do provedor e, com o ufw ativo, no servidor: <code>sudo ufw allow 80/tcp &amp;&amp; sudo ufw allow 443/tcp</code>. O Orbit não abre essas portas por você.</li><li><strong>DNS:</strong> cada domínio próprio passa a precisar de um registro <code>A</code> para cada servidor que recebe tráfego, inclusive subdomínios, que de outro jeito usam um <code>CNAME</code>. A página do domínio lista esses registros, e um domínio que já estava verificado volta a mostrá-los até o Orbit encontrar todos. Os resolvedores espalham os visitantes entre esses endereços, e o Orbit continua roteando um domínio que resolve para qualquer um deles.</li><li><strong>Endereços gerados</strong> (sslip.io) continuam apontando para o servidor principal, já que cada um carrega um IP só.</li><li><strong>Certificados</strong> saem como antes: o Let&#39;s Encrypt consegue validar um domínio por qualquer servidor que recebe tráfego.</li><li><strong>Portas fechadas:</strong> um servidor que não consegue abrir as portas 80 e 443, como um atrás de NAT, pode receber tráfego pelo <a href="./tunnel">Cloudflare Tunnel</a> no lugar.</li><li><strong>Parar:</strong> <strong>Parar de receber tráfego</strong> tira o roteador desse servidor. Tire o endereço dele do seu DNS antes, ou os visitantes cujo resolvedor escolher esse endereço ficam sem resposta.</li></ul><p>O que isso cobre e o que não cobre, medido num cluster de teste com três servidores:</p><ul><li><strong>Perder um servidor que recebe tráfego:</strong> os visitantes cujo resolvedor escolheu esse servidor ficam sem resposta até o DNS deles parar de devolvê-lo. As requisições pelo servidor principal continuaram funcionando, menos as enviadas para a instância que rodava no servidor perdido: 8 de 71 requisições, uma por segundo, falharam nos primeiros 52 segundos, até o Kubernetes declarar o servidor perdido.</li><li><strong>Perder o servidor principal:</strong> os outros servidores continuam respondendo. Com o plano de controle só no principal, ele para junto, então nada tira das listas dos roteadores as instâncias que rodavam lá, e as requisições enviadas para elas falham. Com o <a href="#control-plane">plano de controle em três servidores</a>, os roteadores param de mandar requisições para elas assim que o Kubernetes declara o principal perdido. Veja <a href="./limits#control-plane">o limite do plano de controle</a>.</li></ul><h2 id="control-plane" tabindex="-1">Plano de controle em três servidores <a class="header-anchor" href="#control-plane" aria-label="Permalink to &quot;Plano de controle em três servidores {#control-plane}&quot;">​</a></h2><p>O Kubernetes guarda o estado do cluster e toma as decisões no servidor principal: onde as instâncias rodam, quando elas mudam depois que um servidor se perde, quando um banco faz failover. Com pelo menos três servidores, <strong>Rodar em três servidores</strong> em Servidores coloca isso no principal e em dois servidores que você escolher.</p><ul><li><strong>O que acontece:</strong> o Orbit reserva as portas do etcd, 2379 e 2380, para os seus servidores. Ele reinicia o k3s uma vez no principal para levar os dados do cluster do SQLite para o etcd e depois reinicia o k3s como servidor em cada servidor escolhido, um de cada vez. O Kubernetes fica sem responder por cerca de um minuto no primeiro reinício, e as aplicações continuam rodando. Num cluster de teste, a mudança para o etcd levou de 16 a 18 segundos e cada servidor entrou em 11 a 26 segundos.</li><li><strong>Requisitos:</strong> cada servidor escolhido precisa estar pronto e ter pelo menos 2 GB de memória. Um servidor que não atende não pode ser marcado, e o modal diz o motivo ao lado do nome: ele ainda está sendo configurado, o agente dele está offline, o Kubernetes não o mostra como pronto ou ele tem pouca memória. O K3s recomenda 2 núcleos de CPU e um SSD, porque o etcd escreve com frequência. Seus servidores precisam se alcançar nas portas TCP 2379 e 2380: o Orbit libera isso entre eles no ufw e mantém essas portas fechadas para a internet, mas um firewall do provedor que filtra o tráfego entre servidores também precisa liberar.</li><li><strong>Em quais redes:</strong> os servidores do plano de controle também precisam se alcançar pelos endereços pelos quais o Kubernetes os conhece, os endereços de nó, porque é isso que o k3s anuncia ao etcd. Servidores numa mesma rede privada servem, e servidores cujo endereço público está na própria interface também. Um servidor atrás do NAT do provedor, como uma instância da Oracle Cloud, tem um endereço de nó privado que um servidor fora daquela rede não alcança, então o modal não o oferece ao lado de um servidor principal em outro lugar, e o Orbit confere o caminho a partir do principal antes de mudar qualquer coisa. Um plano de controle espalhado entre provedores precisa de uma rede overlay, que o Orbit ainda não constrói.</li><li><strong>Se um servidor não consegue entrar:</strong> quando o k3s não sobe como servidor em um servidor escolhido, o Orbit devolve esse servidor ao papel de agente, com a configuração restaurada, e a operação mostra o que o k3s reportou lá. A causa comum é um firewall entre os servidores nas portas TCP 2379 ou 2380. Libere o caminho e rode de novo. Um servidor que uma versão anterior do Orbit deixou pela metade volta a ser agente sozinho assim que o Orbit e o agente dele rodarem esta versão.</li><li><strong>Por que três:</strong> o etcd precisa da maioria dos membros. Com três, dá para perder um. Com dois, perder qualquer um para o cluster, o que é pior do que um só, então o console só oferece três.</li><li><strong>Os serviços do próprio cluster:</strong> DNS, cert-manager, o operador de bancos e as métricas passam a poder rodar em qualquer um dos três. O DNS e o operador de bancos rodam duas cópias cada. O K3s devolve os seus próprios serviços ao servidor principal sempre que reinicia num servidor, então o Orbit confere a cada 20 segundos e volta a espalhá-los.</li><li><strong>O próprio Orbit</strong> continua rodando só no principal. Quando ele se perde, o cluster continua funcionando, mas o console e a API esperam o principal voltar.</li></ul><p>Medido três vezes num cluster de teste com três servidores, derrubando o principal:</p><ul><li>O Kubernetes respondeu em outro servidor de 7 a 12 segundos depois.</li><li>Um banco PostgreSQL com três instâncias e o primário no principal teve um novo primário depois de 1 minuto e 30 a 40 segundos.</li><li>A instância da aplicação que rodava no principal voltou a rodar em outro servidor depois de 1 minuto e 43 a 55 segundos.</li><li>Por outro servidor que recebe tráfego, de 10 a 11 de cerca de 155 requisições falharam, a última de 69 a 74 segundos depois da perda. De uma aplicação num terceiro servidor, chamando pelo nome do serviço, de 16 a 17 de cerca de 200 requisições falharam, a última de 71 a 77 segundos depois da perda.</li><li>Uma aplicação publicada depois da perda subiu normalmente.</li></ul><p>Não dá para voltar para um servidor só pelo console, e ele ainda não substitui um servidor do plano de controle perdido. Se um dos três se perder de vez, os outros dois mantêm a maioria, mas perder um segundo para o cluster.</p><h2 id="standbys" tabindex="-1">Cópias do Orbit <a class="header-anchor" href="#standbys" aria-label="Permalink to &quot;Cópias do Orbit {#standbys}&quot;">​</a></h2><p>Com o plano de controle em três servidores, <strong>Manter cópias do Orbit</strong> em Servidores instala o Orbit nos outros dois servidores do plano de controle, onde ele fica esperando como reserva.</p><ul><li><strong>O que uma reserva guarda:</strong> uma cópia do banco do Orbit, da autoridade de certificados e da chave que lacra os segredos. Ela copia tudo uma vez e depois acompanha cada mudança confirmada.</li><li><strong>Quando uma mudança vale:</strong> o Orbit responde a uma mudança quando uma reserva já a tem. Se nenhuma reserva responder em 2 segundos, o Orbit responde mesmo assim, e essa mudança pode se perder se o servidor ativo se perder antes de uma reserva alcançá-la.</li><li><strong>O lease:</strong> o Orbit ativo renova um lease do Kubernetes a cada 2 segundos e para sozinho se não conseguir renovar por 10 segundos. Quando o lease fica 15 segundos sem renovação, a reserva com a cópia mais recente assume e começa a atender.</li><li><strong>Os agentes</strong> passam a conhecer os três endereços e vão para o próximo quando o atual para de responder.</li><li><strong>As operações</strong> que estavam rodando continuam no novo servidor ativo quando o kiln, a fila de jobs do Orbit, declara o antigo perdido, cerca de um minuto depois.</li><li><strong>O console</strong> responde em cada servidor que recebe tráfego, em <code>orbit.&lt;endereço dele com traços&gt;.sslip.io</code>. Coloque as reservas para <a href="#entry">receber tráfego</a> para chegar ao console quando o principal se perder.</li><li><strong>Um servidor que volta</strong> depois de se perder entra como reserva: ele descarta a própria cópia e pega uma nova do servidor ativo.</li></ul><p>Medido num cluster de teste com três servidores, derrubando o principal: uma reserva assumiu o lease depois de 16 a 17 segundos (três rodadas) e respondeu na hora, com o projeto criado logo antes da perda. Um projeto criado depois funcionou, e o principal, quando voltou, entrou como reserva.</p><p>O que isso ainda não cobre:</p><ul><li>os builds rodam onde o BuildKit está instalado, o servidor principal; o novo servidor ativo instala o BuildKit no primeiro build;</li><li>os endereços sslip.io gerados das suas aplicações apontam para o servidor principal;</li><li>o console não adiciona, remove nem substitui uma reserva.</li></ul><h3 id="lost-member" tabindex="-1">Perdendo um membro de vez <a class="header-anchor" href="#lost-member" aria-label="Permalink to &quot;Perdendo um membro de vez {#lost-member}&quot;">​</a></h3><ul><li><strong>Um servidor do plano de controle que não vai voltar:</strong> os dois que sobram continuam funcionando, mas perder mais um pararia o cluster. Rode <code>sudo k3s kubectl delete node &lt;nome&gt;</code> num deles para o Kubernetes parar de esperar por ele; o K3s então tenta tirá-lo do etcd também. O Orbit ainda não coloca outro servidor como membro pelo console.</li><li><strong>Voltar para um servidor só:</strong> o console não tem caminho de volta. Instale o Orbit num servidor novo e restaure o <a href="./operating#backup"><code>orbit backup</code></a> mais recente lá.</li></ul><h2 id="tokens" tabindex="-1">Tokens de entrada <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens de entrada {#tokens}&quot;">​</a></h2><p>Cada servidor guarda um token de entrada do K3s na configuração. Um servidor que entra recebe um token só de agentes, que não consegue adicionar um servidor ao plano de controle: o servidor principal dá aos agentes um token próprio na primeira vez que um servidor entra.</p><p><strong>Renovar tokens de entrada</strong>, no painel do cluster em Servidores, serve para clusters criados antes disso, ou depois de um servidor ter sido exposto. O Orbit então:</p><ol><li>Dá aos agentes um token próprio se eles ainda não tinham, reiniciando o K3s uma vez no servidor principal.</li><li>Grava o token dos agentes na configuração de cada um dos outros servidores, pelo agente dele, sem reiniciar. Um servidor com agente mais antigo fica com o token anterior na configuração, que para de funcionar no passo seguinte.</li><li>Troca o token dos servidores (<code>k3s token rotate</code>) e reinicia o K3s mais uma vez no servidor principal. A partir daí, um token copiado de qualquer servidor não coloca mais nenhuma máquina no cluster.</li></ol><p>As aplicações continuam rodando o tempo todo, e os servidores que já estão no cluster continuam nele. É recusado enquanto um servidor está sendo instalado, e em clusters cujo plano de controle roda em vários servidores.</p><h2 id="builds" tabindex="-1">Builds e atualizações <a class="header-anchor" href="#builds" aria-label="Permalink to &quot;Builds e atualizações {#builds}&quot;">​</a></h2><ul><li>Os builds rodam no servidor principal. Uma aplicação de repositório pode rodar num servidor da mesma arquitetura: o Orbit copia a imagem para lá antes de cada deploy.</li><li>Atualizar pelo console também atualiza os agentes dos outros servidores e o Orbit nas reservas. O <code>install.sh</code> atualiza só o servidor onde roda.</li></ul><h2 id="agents" tabindex="-1">Agentes <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agentes {#agents}&quot;">​</a></h2><p>O agente de cada servidor informa a saúde e o inventário dele por TLS mútuo. Um servidor fica <strong>offline</strong> cerca de 90 segundos depois do último sinal, e o console passa a mostrar os workloads dele como desconhecidos.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revoke-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> srv_…</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # recusa o agente daquele servidor na hora</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enroll-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> srv_…</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # na mesma máquina: token novo, certificado novo, agente reiniciado</span></span></code></pre></div><p>Os ids dos servidores estão no <code>orbit status</code>. Quando um agente se registra, os certificados que o servidor tinha antes são revogados, então só o registro mais novo vale.</p><h2 id="looking" tabindex="-1">Olhando o cluster <a class="header-anchor" href="#looking" aria-label="Permalink to &quot;Olhando o cluster {#looking}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nodes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit.cortexlabs.dev/server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wide</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k3s-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # no outro servidor</span></span></code></pre></div><h2 id="costs" tabindex="-1">Quanto custam seus servidores <a class="header-anchor" href="#costs" aria-label="Permalink to &quot;Quanto custam seus servidores {#costs}&quot;">​</a></h2><p>Informe quanto custa cada servidor no card dele em <strong>Servidores</strong>: o valor mensal da conta do seu provedor, na moeda dela. Só administradores do Orbit podem definir ou remover um preço.</p><p>O Orbit então divide o preço de cada servidor entre os projetos cujos serviços reservam recursos nele:</p><ul><li>A parte de um serviço é o que ele reserva naquele servidor, com CPU e memória pesando metade cada, sobre o que o servidor oferece depois de separada a reserva do próprio Orbit. Uma aplicação espalhada por vários servidores paga em cada um pelas instâncias que mantém ali, e um banco paga pela memória em cada servidor que guarda uma cópia.</li><li>O custo de um projeto é a soma das partes dos seus serviços, ambientes de preview incluídos.</li><li>O que nenhum serviço reserva aparece como <strong>Não reservado</strong>, e os projetos de outros workspaces contam juntos como uma parte só, sem os nomes.</li><li>Em cada servidor, as partes somam o preço dele até o centavo. Preços em moedas diferentes nunca são somados: cada moeda tem o seu total.</li></ul><p><strong>Projetos</strong> mostra o total e quanto cada projeto custa por mês. A visão geral mostra o mesmo total e onde o dinheiro fica parado: a parte de cada servidor que ninguém reserva, e serviços cuja instância mais ocupada usa menos de um terço da memória que reserva. Diminuir essas reservas em <a href="./applications#resources">Recursos</a> do serviço libera espaço para outros projetos.</p><p>Servidores ainda sendo adicionados ficam de fora, e servidores sem preço aparecem listados para você definir um.</p>`,48)])])}const v=o(i,[["render",d]]);export{m as __pageData,v as default};
